import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Dashboard(props) {
  const [scholarships, setScholarships] = useState([]);
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const role = localStorage.getItem("designation");
    const token = localStorage.getItem("token");

    if (role !== "admin") {
      setMessage("Access denied: Admins only");
      return;
    }

    const fetchScholarships = async () => {
      try {
        const res = await fetch(props.getendpoint, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        const data = await res.json();
        if (res.ok) {
          setScholarships(data);
        } else {
          setMessage(data.message || "Failed to fetch scholarships");
        }
      } catch (err) {
        setMessage("Server error while fetching scholarships");
      }
    };

    fetchScholarships();
  }, [props.getendpoint]);

  const handlePostClick = () => {
    navigate("/postscholarship");
  };

  return (
    <div className="container my-5">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2 className="fw-bold">Manage Scholarships</h2>
        <button className="btn btn-primary" onClick={handlePostClick}>
          + Post Scholarship
        </button>
      </div>

      {message && (
        <div
          className={`alert ${
            message.includes("denied") || message.includes("error")
              ? "alert-danger"
              : "alert-success"
          }`}
        >
          {message}
        </div>
      )}

      {scholarships.length > 0 ? (
        <div className="table-responsive">
          <table className="table table-bordered table-hover align-middle text-center">
            <thead className="table-dark">
              <tr>
                <th>#</th>
                <th>Title</th>
                <th>Organization</th>
                <th>Description</th>
                <th>Deadline</th>
                <th>Amount</th>
              </tr>
            </thead>
            <tbody>
              {scholarships.map((sch, index) => (
                <tr key={sch._id || index}>
                  <td>{index + 1}</td>
                  <td>{sch.title}</td>
                  <td>{sch.organization}</td>
                  <td>{sch.description}</td>
                  <td>{new Date(sch.deadline).toLocaleDateString()}</td>
                  <td>{sch.amount}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        !message && <p className="text-center text-muted">No scholarships posted yet.</p>
      )}
    </div>
  );
}
